$(function () {
    console.log("jQuery loaded!");

    // Check if cartModal is set to true
    if (new URLSearchParams(window.location.search).get('cartModal') === 'true') {
        $('#cartModal').modal('show');
        $('body').addClass('modal-open').css('padding-right', '0px');
    }

    // Close modal with the backdrop
    $(document).on('click', '.modal-backdrop', function () {
        window.location.href = $('#cartModal').data('close-url');
    });

    // Ajax requests for dropdowns (unchanged)
    $('#country').change(function () {
        var selectedCountry = $(this).val();
        $.ajax({
            type: 'GET',
            url: '/meet-your-meal/fetch-cities',
            data: { country: selectedCountry },
            success: function (cities) {
                $('#city').empty().append($('<option>').val('').text('City'));
                $.each(cities, function (index, city) {
                    $('#city').append($('<option>').val(city).text(city));
                });
            },
            error: function () {
                console.error("Failed to fetch cities for the selected country.");
            }
        });
    });

    $('#city').change(function () {
        var selectedCountry = $('#country').val();
        var selectedCity = $(this).val();
        $.ajax({
            type: 'GET',
            url: '/meet-your-meal/fetch-postal-codes',
            data: { country: selectedCountry, city: selectedCity },
            success: function (postalCodes) {
                $('#postalCode').empty().append($('<option>').val('').text('Postal code'));
                $.each(postalCodes, function (index, postalCode) {
                    $('#postalCode').append($('<option>').val(postalCode).text(postalCode));
                });
            },
            error: function () {
                console.error("Failed to fetch postal codes for the selected city.");
            }
        });
    });

    $('#postalCode').change(function () {
        var selectedCountry = $('#country').val();
        var selectedCity = $('#city').val();
        var selectedPostalCode = $(this).val();
        $.ajax({
            type: 'GET',
            url: '/meet-your-meal/fetch-streets',
            data: { country: selectedCountry, city: selectedCity, postalCode: selectedPostalCode },
            success: function (streets) {
                $('#street').empty().append($('<option>').val('').text('Street'));
                $.each(streets, function (index, street) {
                    $('#street').append($('<option>').val(street).text(street));
                });
            },
            error: function () {
                console.error("Failed to fetch streets for the selected postal code.");
            }
        });
    });
});